content:
    ctx.fillRect(1, 1, 62 * r, 6);
    this._barTex.needsUpdate = true;
  }

  spawnAt(pos) {
    // 碰撞解算：出生点随机偏移可能落入墙/掩体内，先推出到安全位置
    const r = this.map.collide(pos.x, pos.z, this.radius);
    this.position.set(r.x, 0, r.z);
    this.velocity.set(0, 0, 0);
    this.health = this.maxHealth;
    this.alive = true;
    this.state = 'idle';
    this.seePlayer = false;
    this.mesh.visible = true;
    this.mesh.rotation.set(0, 0, 0);
    this.mesh.position.copy(this.position);
    this._barSprite.visible = false;
    this._stuckTimer = 0;
    this._escapeTimer = 0;
    this._lastPos.copy(this.position);
  }

  // ---------- 受击 ----------
  takeDamage(amount, part) {
    if (!this.alive) return false;
    this.health -= amount;
    this._barSprite.visible = true;
    this._drawBar();
    // 受击立刻进入战斗
    if (this.state === 'idle') {
      this.state = 'engage';
      this.lastSeenPos = this.player.getFeet().clone();
    }
    if (this.health <= 0) {
      this._die();
      return true;
    }
    return false;
  }

  _die() {
    this.alive = false;
    this.state = 'dead';
    this.deathTimer = 2.0;
    this._barSprite.visible = false;
    // 倒地动画：整体旋转倒下
  }

  // ---------- 视线检测 ----------
  _canSeePlayer() {
    const eye = new THREE.Vector3(this.position.x, 1.6, this.position.z);
    const target = this.player.getEye();
    const to = target.clone().sub(eye);
    const dist = to.length();
    if (dist > CONFIG.enemy.sightRange) return false;
    to.normalize();
    // 视野角（敌人朝向）
    const fwd = new THREE.Vector3(-Math.sin(this.facing), 0, -Math.cos(this.facing));
    const dot = fwd.dot(to.clone().setY(0).normalize());
    const angle = Math.acos(Math.max(-1, Math.min(1, dot)));
    // FOV 检测：在视野内或距离很近
    if (angle > CONFIG.enemy.fov && dist > 6) return false;
    // 墙遮挡
    const wallDist = this.map.raycast(eye, to, dist);
    return wallDist >= dist - 0.5;
  }

  // ---------- 主更新 ----------
  update(dt) {
    if (!this.alive) {
      // 倒地动画
      if (this.deathTimer > 0) {
        this.deathTimer -= dt;
        const fall = Math.min(1, (2 - this.deathTimer) / 0.5);
        this.mesh.rotation.x = fall * (Math.PI / 2) * 0.9;
        this.mesh.position.y = -fall * 0.3;
        if (this.deathTimer <= 0) this.mesh.visible = false;
      }
      return;
    }

    // 检测视线（节流：每 0.12s 一次；射线需遍历 30+ 碰撞盒，每帧每个敌人都做开销大）
    this._seeTimer = (this._seeTimer || 0) - dt;
    let seen = this.seePlayer;   // 节流间隔内沿用上次结果
    if (this._seeTimer <= 0) {
      this._seeTimer = 0.12;
      seen = this._canSeePlayer();
      this.seePlayer = seen;
    }
    if (seen) {
      this.lastSeenPos = this.player.getFeet().clone();
      if (this.state === 'idle') {
        this.reactionTimer = CONFIG.enemy.reactionTime;
        this.state = 'react';
      }
    }

    // 行为状态机
    const toPlayer = this.player.getFeet().clone().sub(this.position);
    toPlayer.y = 0;
    const dist = toPlayer.length();
    const dirToPlayer = dist > 0.01 ? toPlayer.clone().multiplyScalar(1 / dist) : new THREE.Vector3();

    // 反应期
    if (this.state === 'react') {
      this.reactionTimer -= dt;
      if (this.reactionTimer <= 0) this.state = 'engage';
      this._moveTowards(dirToPlayer, dt, 0);   // 反应期不动
    } else if (this.state === 'engage') {
      this._engage(dist, dirToPlayer, dt, seen);
    }

    // 朝向：始终面向玩家或移动方向
    if (this.state !== 'idle') {
      this.facing = Math.atan2(-dirToPlayer.x, -dirToPlayer.z);
    }

    // ---- 卡墙检测：有移动意图但位移过小，累计 1s 判定卡住 ----
    if (this.state === 'engage' || this.state === 'react') {
      const moved = Math.hypot(this.position.x - this._lastPos.x, this.position.z - this._lastPos.z);
      this._lastPos.copy(this.position);
      if (this._wantsMove && moved < 0.03) {
        this._stuckTimer += dt;
        if (this._stuckTimer > 1.0) {
          this._stuckTimer = 0;
          this.strafeDir *= -1;        // 反转横移方向
          this._escapeTimer = 0.8;     // 接下来 0.8s 强制侧向逃离
        }
      } else {
        this._stuckTimer = 0;
      }
    } else {
      this._lastPos.copy(this.position);
      this._stuckTimer = 0;
    }

    // 应用位置
    this.mesh.position.set(this.position.x, this.position.y, this.position.z);
    this.mesh.rotation.y = this.facing;

    // 走路腿部摆动
    const sp = Math.hypot(this.velocity.x, this.velocity.z);
    if (sp > 0.3) {
      this._walkPhase += dt * sp * 3;
      this._legL.rotation.x = Math.sin(this._walkPhase) * 0.5;
      this._legR.rotation.x = -Math.sin(this._walkPhase) * 0.5;
    } else {
      this._legL.rotation.x *= 0.8;
      this._legR.rotation.x *= 0.8;
    }
  }

  _engage(dist, dirToPlayer, dt, seen) {
    const E = CONFIG.enemy;
    let moveDir = new THREE.Vector3();
    let curSpeed = 0;

    // 卡墙强制逃离：短时间只走侧向（不开火），优先解困
    if (this._escapeTimer > 0) {
      this._escapeTimer -= dt;
      const side = new THREE.Vector3(-dirToPlayer.z, 0, dirToPlayer.x).multiplyScalar(this.strafeDir);
      this._moveTowards(side, dt, this.speed);
      return;
    }

    // 距离过远 → 接近；过近 → 后撤；合适 → 横向移动（strafe）
    if (dist > 18) {
      moveDir.copy(dirToPlayer);
      curSpeed = this.speed * 1.3;
    } else if (dist < 6) {
      moveDir.copy(dirToPlayer).multiplyScalar(-1);
      curSpeed = this.speed;
    } else {
      // 中距离：横向绕圈
      this.strafeTimer -= dt;
      if (this.strafeTimer <= 0) {
        this.strafeDir *= -1;
        this.strafeTimer = 1 + Math.random() * 2;
      }
      // 偶尔向玩家靠近
      if (dist > 12) moveDir.add(dirToPlayer.multiplyScalar(0.5));
      // 横向
      const side = new THREE.Vector3(-dirToPlayer.z, 0, dirToPlayer.x).multiplyScalar(this.strafeDir);
      moveDir.add(side);
      if (moveDir.lengthSq() > 0) moveDir.normalize();
      curSpeed = this.speed * 0.9;
    }
    this._moveTowards(moveDir, dt, curSpeed);

    // 开火
    this.fireCooldown -= dt;
    if (seen && dist < E.fireRange && this.fireCooldown <= 0) {
      this._fireBurst(dist);
      this.fireCooldown = E.fireInterval + Math.random() * 0.4;
      this.burstLeft = E.burstCount;
    }
    // 点射间隔
    if (this.burstLeft > 0) {
      this.burstTimer -= dt;
      if (this.burstTimer <= 0) {
        this._shootOnce(dist);
        this.burstLeft--;
        this.burstTimer = E.burstDelay;
      }
    }
  }

  _moveTowards(dir, dt, speed) {
    this._wantsMove = speed > 0 && dir.lengthSq() > 0;
    if (!this._wantsMove) {
      this.velocity.x *= 0.8; this.velocity.z *= 0.8;
      return;
    }
    this.velocity.x = dir.x * speed;
    this.velocity.z = dir.z * speed;
    // 积分
    let nx = this.position.x + this.velocity.x * dt;
    let nz = this.position.z + this.velocity.z * dt;
    const r = this.map.collide(nx, nz, this.radius);
    const pushX = r.x - nx, pushZ = r.z - nz;
    const blocked = Math.abs(pushX) > 0.001 || Math.abs(pushZ) > 0.001;
    if (blocked) {
      // 滑墙：把速度中撞墙法线方向的分量移除，剩余切向分量继续移动
      const len = Math.hypot(pushX, pushZ) || 1;
      const nX = pushX / len, nZ = pushZ / len;
      const dot = this.velocity.x * nX + this.velocity.z * nZ;
      if (dot < 0) {
        let sX = this.velocity.x - dot * nX;
        let sZ = this.velocity.z - dot * nZ;
        const sLen = Math.hypot(sX, sZ);
        if (sLen > 0.001) {
          // 切向速度归一化到原速（保持移动节奏）
          sX = (sX / sLen) * speed;
          sZ = (sZ / sLen) * speed;
          const altX = this.position.x + sX * dt;
          const altZ = this.position.z + sZ * dt;
          const r2 = this.map.collide(altX, altZ, this.radius);
          if (Math.abs(r2.x - altX) < 0.001 && Math.abs(r2.z - altZ) < 0.001) {
            nx = r2.x; nz = r2.z;
          } else {
            nx = r.x; nz = r.z;   // 切向也被挡 → 原地，交给卡墙检测换向
          }
        }
      } else {
        nx = r.x; nz = r.z;
      }
    }
    this.position.set(nx, 0, nz);
  }

  _fireBurst(dist) {
    this.burstTimer = 0;
  }

  _shootOnce(dist) {
    const E = CONFIG.enemy;
    // 命中率随距离衰减
    const acc = E.hitChance * Math.max(0.3, 1 - dist / E.fireRange);
    if (Math.random() < acc) {
      // 是否暴击（头）：小概率
      const head = Math.random() < 0.12;
      const dmg = head ? E.damage * 3 : E.damage * (0.7 + Math.random() * 0.6);
      this.player.takeDamage(dmg);
      // 枪口火光（敌人朝向玩家）
    }
    // 音效
    if (this.hud.audio) this.hud.audio.enemyShot();
  }

  dispose() {
    this.scene.remove(this.mesh);
  }
}

